import {sessionViewport} from './viewport.mjs';
import {MAX_SHOTS,TARGETS,clamp,shotVelocity,targetScore} from './engine.mjs';
import {mountGameProgress,recordEvent} from './progression.mjs';
if(typeof mountGameProgress==='function')mountGameProgress('desk-shot');
const c=document.querySelector('#desk'),ctx=c.getContext('2d'),game=document.querySelector('#game'); const $=s=>document.querySelector(s); let W=1,H=1,dpr=1,running=false,paused=false,shotActive=false,drag=null,shots=MAX_SHOTS,score=0,banks=0,last=0,resetAt=0,hitStreak=0; let best=Number(localStorage.getItem('shrunk-deskshot-best')||0); const puck={x:0,y:0,vx:0,vy:0,r:13};
let orientationBlocked=innerHeight>=innerWidth;
function resize(){if(orientationBlocked)return;dpr=Math.min(devicePixelRatio||1,2);W=window.visualViewport?.width||innerWidth;H=window.visualViewport?.height||innerHeight;c.width=W*dpr;c.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(!running)homePuck();} addEventListener('resize',resize);resize();
function homePuck(){puck.x=W*.18;puck.y=H*.67;puck.vx=puck.vy=0;shotActive=false;banks=0;resetAt=0}
function sync(){ $('#score').textContent=String(score).padStart(4,'0');$('#best').textContent=best;$('#shots').textContent=shots }
function start(){running=true;paused=false;shots=MAX_SHOTS;score=0;hitStreak=0;$('#start').hidden=true;$('#results').hidden=true;game.dataset.state='play';homePuck();sync()}
$('#play').onclick=start;$('#replay').onclick=start;$('#pause').onclick=()=>{if(!running)return;paused=true;$('#pausebox').showModal()};$('#resume').onclick=()=>{paused=false;$('#pausebox').close()};$('#restart').onclick=()=>{$('#pausebox').close();start()};
function point(e){const r=c.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
c.addEventListener('pointerdown',e=>{if(!running||paused||orientationBlocked||shotActive)return;const p=point(e);if(Math.hypot(p.x-puck.x,p.y-puck.y)<55){drag={id:e.pointerId,x:p.x,y:p.y};c.setPointerCapture?.(e.pointerId)}});c.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const p=point(e);drag.x=p.x;drag.y=p.y});function release(e){if(!drag||e.pointerId!==drag.id)return;const p=point(e),v=shotVelocity(puck.x-p.x,puck.y-p.y);drag=null;if(!v)return;puck.vx=v.vx;puck.vy=v.vy;shotActive=true;shots--;banks=0;sync()} c.addEventListener('pointerup',release);c.addEventListener('pointercancel',e=>{if(drag&&e.pointerId===drag.id)drag=null});
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),850)}
function finishShot(){if(resetAt)return;resetAt=performance.now()+650}
function finishRound(){running=false;recordEvent('desk_round_complete',{score},'desk-shot');if(score>best){best=score;localStorage.setItem('shrunk-deskshot-best',best);$('#bestline').textContent='NEW PERSONAL BEST'}else $('#bestline').textContent='PERSONAL BEST '+best;$('#final').textContent=String(score).padStart(4,'0');sync();$('#results').hidden=false}
function update(dt,t){if(!running||paused||orientationBlocked)return;if(resetAt&&t>=resetAt){resetAt=0;if(shots<=0)finishRound();else homePuck();return} if(!shotActive)return;puck.x+=puck.vx*dt;puck.y+=puck.vy*dt;const top=82,bottom=H-20,left=15,right=W-15;if(puck.x-puck.r<left){puck.x=left+puck.r;puck.vx=Math.abs(puck.vx)*.78;banks++}if(puck.x+puck.r>right){puck.x=right-puck.r;puck.vx=-Math.abs(puck.vx)*.78;banks++}if(puck.y-puck.r<top){puck.y=top+puck.r;puck.vy=Math.abs(puck.vy)*.78;banks++}if(puck.y+puck.r>bottom){puck.y=bottom-puck.r;puck.vy=-Math.abs(puck.vy)*.78;banks++}puck.vx*=Math.pow(.988,dt*60);puck.vy*=Math.pow(.988,dt*60);
function bankBar(cx,cy,w,h,a){const ca=Math.cos(a),sa=Math.sin(a),dx=puck.x-cx,dy=puck.y-cy,lx=dx*ca+dy*sa,ly=-dx*sa+dy*ca,hx=w/2+puck.r,hy=h/2+puck.r;if(Math.abs(lx)>=hx||Math.abs(ly)>=hy)return;let nx=0,ny=0;if(hx-Math.abs(lx)<hy-Math.abs(ly))nx=lx<0?-1:1;else ny=ly<0?-1:1;const wx=nx*ca-ny*sa,wy=nx*sa+ny*ca,dot=puck.vx*wx+puck.vy*wy;if(dot<0){puck.vx=(puck.vx-2*dot*wx)*.8;puck.vy=(puck.vy-2*dot*wy)*.8;banks++}}
bankBar(W*.28,H*.25,W*.18,H*.14,-.08);bankBar(W*.58,H*.78,W*.26,10,-.12);bankBar(W*.76,H*.58,W*.16,9,.24);bankBar(W*.38,H*.62,W*.10,16,-.30);
// giant tape roll obstacle
const ox=W*.49,oy=H*.48,or=Math.min(W,H)*.095,dd=Math.hypot(puck.x-ox,puck.y-oy);if(dd<or+puck.r){const nx=(puck.x-ox)/(dd||1),ny=(puck.y-oy)/(dd||1),dot=puck.vx*nx+puck.vy*ny;if(dot<0){puck.x=ox+nx*(or+puck.r);puck.y=oy+ny*(or+puck.r);puck.vx=(puck.vx-2*dot*nx)*.8;puck.vy=(puck.vy-2*dot*ny)*.8;banks++}}
for(const tg of TARGETS){const x=W*tg.x,y=H*tg.y,r=Math.min(W,H)*tg.r;if(Math.hypot(puck.x-x,puck.y-y)<r+puck.r){const speed=Math.hypot(puck.vx,puck.vy),res=targetScore(tg.points,banks,clamp(speed/650,0,1));hitStreak++;const streakBonus=hitStreak>1?25*(hitStreak-1):0;const trickBonus=banks>=2?75:0;score+=res.points+streakBonus+trickBonus;recordEvent('desk_target_hit',{banks,points:res.points+streakBonus+trickBonus,score},'desk-shot');sync();toast('+'+(res.points+streakBonus+trickBonus)+(banks>=2?'  TRICK SHOT':res.mult>1?'  BANK ×'+res.mult:'')+(streakBonus?'  STREAK':''));puck.vx*=.2;puck.vy*=.2;finishShot();break}}
if(Math.hypot(puck.vx,puck.vy)<14){if(!resetAt)hitStreak=0;finishShot()}}
function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}function draw(){if(orientationBlocked||W<2||H<2)return;ctx.clearRect(0,0,W,H);const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#7b6549');g.addColorStop(1,'#4b3b2c');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.globalAlpha=.12;for(let y=0;y<H;y+=22){ctx.fillStyle=y%44?'#fff':'#000';ctx.fillRect(0,y,W,1)}ctx.globalAlpha=1;
// book ramp
ctx.save();ctx.translate(W*.28,H*.25);ctx.rotate(-.08);ctx.fillStyle='#24372d';rounded(-W*.09,-H*.07,W*.18,H*.14,8);ctx.fill();ctx.fillStyle='#c4fb71';ctx.font='700 11px Arial';ctx.fillText('SHRUNK NOTES',-W*.07,0);ctx.restore();
// pencil bumper
ctx.save();ctx.translate(W*.58,H*.78);ctx.rotate(-.12);ctx.fillStyle='#e3c65c';rounded(-W*.13,-5,W*.26,10,5);ctx.fill();ctx.restore();
// extra ruler and eraser banks
ctx.save();ctx.translate(W*.76,H*.58);ctx.rotate(.24);ctx.fillStyle='#d8b07a';rounded(-W*.08,-4.5,W*.16,9,4);ctx.fill();ctx.restore();ctx.save();ctx.translate(W*.38,H*.62);ctx.rotate(-.30);ctx.fillStyle='#d88989';rounded(-W*.05,-8,W*.10,16,4);ctx.fill();ctx.restore();
// tape roll
const ox=W*.49,oy=H*.48,or=Math.min(W,H)*.095;ctx.strokeStyle='#ded8c9';ctx.lineWidth=18;ctx.beginPath();ctx.arc(ox,oy,or-8,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#8d897f';ctx.lineWidth=2;ctx.stroke();
for(const tg of TARGETS){const x=W*tg.x,y=H*tg.y,r=Math.min(W,H)*tg.r;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=tg.points===100?'#c4fb71':'#ece8dd';ctx.fill();ctx.beginPath();ctx.arc(x,y,r*.65,0,Math.PI*2);ctx.strokeStyle='#17201a';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#17201a';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`900 ${Math.max(13,r*.48)}px Impact,Arial Black`;ctx.fillText(tg.label,x,y)}
// puck + aim
if(drag&&!shotActive){const dx=puck.x-drag.x,dy=puck.y-drag.y,m=Math.hypot(dx,dy),nx=dx/(m||1),ny=dy/(m||1),len=Math.min(m,150);ctx.setLineDash([7,7]);ctx.strokeStyle='#c4fb71';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(puck.x,puck.y);ctx.lineTo(puck.x+nx*len*1.25,puck.y+ny*len*1.25);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#ffffff88';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(puck.x,puck.y);ctx.lineTo(drag.x,drag.y);ctx.stroke()}ctx.beginPath();ctx.arc(puck.x,puck.y,puck.r,0,Math.PI*2);ctx.fillStyle='#101713';ctx.fill();ctx.strokeStyle='#c4fb71';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#c4fb71';ctx.beginPath();ctx.arc(puck.x-3,puck.y-3,3,0,Math.PI*2);ctx.fill();}
function frame(t){const dt=Math.min((t-last)/1000||0,.033);last=t;update(dt,t);draw();requestAnimationFrame(frame)}sync();requestAnimationFrame(frame);
let orientationSince=0;sessionViewport(v=>{const was=orientationBlocked;orientationBlocked=v.blocked;if(v.blocked){const id=drag?.id;drag=null;if(id!==undefined&&c.hasPointerCapture(id))c.releasePointerCapture(id);if(!orientationSince)orientationSince=performance.now();}else{if(orientationSince&&resetAt)resetAt+=performance.now()-orientationSince;orientationSince=0;const shell=document.querySelector('main');shell.style.cssText=`position:fixed;left:${v.left}px;top:${v.top}px;width:${v.width}px;height:${v.height}px`;resize();last=performance.now();}});
